final class GCU_Repository{
const MAX_CONTENT_TITLE=240,MAX_CONTENT_BODY=5000,MAX_REASON=500,EVENT_RETENTION_DAYS=90;
public function active_blocks($slot='',$audience='all',$locale='en-US'){global$wpdb;$t=GCU_Install::tables();$slot=sanitize_key($slot);$audience=GCU_Policy::sanitize_audience($audience);$locale=GCU_Policy::sanitize_locale($locale);$w="b.status='active' AND p.status='active' AND b.locale=%s AND (b.review_due_at IS NULL OR b.review_due_at>UTC_TIMESTAMP())";$a=array($locale);if($slot){$w.=' AND p.slot_key=%s';$a[]=$slot;}if('all'!==$audience){$w.=" AND (p.audience=%s OR p.audience='all') AND (b.audience=%s OR b.audience='all')";$a[]=$audience;$a[]=$audience;}$sql="SELECT b.public_id,b.block_key,b.audience,b.block_type,b.slot_key,b.locale,b.title,b.body,b.cta_label,b.cta_destination,b.claim_keys,b.content_version,p.route_key,p.priority FROM {$t['blocks']} b INNER JOIN {$t['placements']} p ON p.block_key=b.block_key AND p.slot_key=b.slot_key WHERE $w AND b.content_version=(SELECT MAX(b2.content_version) FROM {$t['blocks']} b2 WHERE b2.block_key=b.block_key AND b2.locale=b.locale AND b2.status='active') AND (p.starts_at IS NULL OR p.starts_at<=UTC_TIMESTAMP()) AND (p.ends_at IS NULL OR p.ends_at>UTC_TIMESTAMP()) ORDER BY p.priority ASC,b.id ASC LIMIT 100";$r=$wpdb->get_results($wpdb->prepare($sql,$a),ARRAY_A);if(!is_array($r)){return array();}$all_claims=array();foreach($r as&$row){$row['claim_keys']=json_decode((string)$row['claim_keys'],true);if(!is_array($row['claim_keys'])){$row['claim_keys']=array();}$all_claims=array_merge($all_claims,$row['claim_keys']);}unset($row);$valid=$this->public_claims($all_claims);$r=array_values(array_filter($r,static function($row)use($valid){foreach($row['claim_keys']as$key){if(!isset($valid[$key])){return false;}}return GCU_Plugin::instance()->contracts()->placement_ready($row);}));return$r;}
public function public_claims(array$keys){global$wpdb;$keys=array_values(array_unique(array_filter(array_map('sanitize_key',$keys))));if(!$keys){return array();}$t=GCU_Install::tables();$m=implode(',',array_fill(0,count($keys),'%s'));$sql="SELECT claim_key,claim_text,basis,owner_name,source_uri,effective_at,review_due_at,expires_at FROM {$t['claims']} WHERE claim_key IN ($m) AND status='active' AND is_public=1 AND effective_at<=UTC_TIMESTAMP() AND (review_due_at IS NULL OR review_due_at>UTC_TIMESTAMP()) AND (expires_at IS NULL OR expires_at>UTC_TIMESTAMP()) ORDER BY claim_key ASC";$rows=$wpdb->get_results($wpdb->prepare($sql,$keys),ARRAY_A);$out=array();foreach(is_array($rows)?$rows:array()as$row){$out[$row['claim_key']]=$row;}return$out;}
public function create_content_draft(array$d,$actor){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}$auth=GCU_Capabilities::require_capability(GCU_Capabilities::MANAGE_CONTENT,null,'create_content_draft');if(is_wp_error($auth)){return$auth;}global$wpdb;$t=GCU_Install::tables();$key=sanitize_key(isset($d['block_key'])?$d['block_key']:'');$loc=GCU_Policy::sanitize_locale(isset($d['locale'])?$d['locale']:'en-US');$slot=sanitize_key(isset($d['slot_key'])?$d['slot_key']:'global_clinic_primary');$type=sanitize_key(isset($d['block_type'])?$d['block_type']:'content');$title=GCU_Hardening::bounded_text(sanitize_text_field(isset($d['title'])?$d['title']:''),self::MAX_CONTENT_TITLE);$body=wp_kses_post(isset($d['body'])?$d['body']:'');$plain=trim(wp_strip_all_tags($body));$dest=sanitize_key(isset($d['cta_destination'])?$d['cta_destination']:'');if(!$key||!in_array($slot,array('global_clinic_primary','global_clinic_trust','global_clinic_steps','global_clinic_faq'),true)||!in_array($type,array('hero','trust','steps','faq','content'),true)||''===$title||''===$plain){return new WP_Error('gcu_invalid_content',__('The File 14 content record is incomplete or outside its approved scope.','global-clinic-usp-integration'),array('status'=>400));}$len=function_exists('mb_strlen')?mb_strlen($plain):strlen($plain);if($len>self::MAX_CONTENT_BODY){return new WP_Error('gcu_content_too_long',__('The content body exceeds the approved File 14 bound.','global-clinic-usp-integration'),array('status'=>400));}if($dest&&!array_key_exists($dest,GCU_Plugin::instance()->contracts()->destination_registry())){return new WP_Error('gcu_invalid_destination',__('The CTA destination is not a registered File 14 contract.','global-clinic-usp-integration'),array('status'=>400));}$claims=array_values(array_unique(array_filter(array_map('sanitize_key',isset($d['claim_keys'])&&is_array($d['claim_keys'])?$d['claim_keys']:array()))));if(count($claims)>20){return new WP_Error('gcu_claim_set_too_large',__('Too many claims were attached to one content block.','global-clinic-usp-integration'),array('status'=>400));}$lock=GCU_Hardening::acquire_db_lock('content:'.$key.':'.$loc);if(!$lock){return new WP_Error('gcu_content_lock_busy',__('Another content version is being created. Please retry.','global-clinic-usp-integration'),array('status'=>409));}try{$latest=(int)$wpdb->get_var($wpdb->prepare("SELECT MAX(content_version) FROM {$t['blocks']} WHERE block_key=%s AND locale=%s",$key,$loc));$now=current_time('mysql',true);$r=array('public_id'=>wp_generate_uuid4(),'block_key'=>$key,'audience'=>GCU_Policy::sanitize_audience(isset($d['audience'])?$d['audience']:'all'),'block_type'=>$type,'slot_key'=>$slot,'locale'=>$loc,'title'=>$title,'body'=>$body,'cta_label'=>GCU_Hardening::bounded_text(sanitize_text_field(isset($d['cta_label'])?$d['cta_label']:''),120),'cta_destination'=>$dest,'claim_keys'=>wp_json_encode($claims),'status'=>'draft','content_version'=>$latest+1,'created_by'=>absint($actor),'created_at'=>$now,'updated_at'=>$now);if(false===$wpdb->insert($t['blocks'],$r)){return new WP_Error('gcu_write_failed',__('The content version could not be created.','global-clinic-usp-integration'),array('status'=>500));}}finally{GCU_Hardening::release_db_lock($lock);}$this->audit('content_created','content_block',$r['public_id'],'content_governance','',array(),$r);return$this->content_by_public_id($r['public_id']);}
public function transition($machine,$id,$expected,$target,$reason=''){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}$machine=sanitize_key($machine);$target=sanitize_key($target);$map=array('copy'=>array('table'=>'blocks','cap'=>GCU_Capabilities::MANAGE_CONTENT),'placement'=>array('table'=>'placements','cap'=>GCU_Capabilities::MANAGE_PLACEMENTS),'experiment'=>array('table'=>'experiments','cap'=>GCU_Capabilities::MANAGE_EXPERIMENTS));if(!isset($map[$machine])){return new WP_Error('gcu_invalid_machine',__('Unknown workflow type.','global-clinic-usp-integration'),array('status'=>400));}$auth=GCU_Capabilities::require_capability($map[$machine]['cap'],$id,'transition_'.$machine);if(is_wp_error($auth)){return$auth;}if(('copy'===$machine&&in_array($target,array('founder_approved','active','withdrawn'),true))||('placement'===$machine&&'active'===$target)||('experiment'===$machine&&in_array($target,array('approved','running','adopted'),true))){$a=GCU_Capabilities::require_capability(GCU_Capabilities::APPROVE_CLAIMS,$id,'governed_approval');if(is_wp_error($a)){return$a;}}global$wpdb;$t=GCU_Install::tables();$table=$t[$map[$machine]['table']];$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM `$table` WHERE public_id=%s",sanitize_text_field($id)),ARRAY_A);if(!$row){return new WP_Error('gcu_not_found',__('The requested record was not found.','global-clinic-usp-integration'),array('status'=>404));}if((int)$row['row_version']!==(int)$expected){return new WP_Error('gcu_version_conflict',__('The record changed. Reload it before retrying.','global-clinic-usp-integration'),array('status'=>409,'current_version'=>(int)$row['row_version']));}if(!GCU_Policy::transition_allowed($machine,$row['status'],$target)){return new WP_Error('gcu_invalid_transition',__('This state transition is not allowed.','global-clinic-usp-integration'),array('status'=>409));}$v=$this->validate_transition_target($machine,$row,$target);if(is_wp_error($v)){return$v;}$scope='workflow:'.$machine.':'.('copy'===$machine?$row['block_key'].':'.$row['locale']:$id);$lock=GCU_Hardening::acquire_db_lock($scope);if(!$lock){return new WP_Error('gcu_workflow_lock_busy',__('Another workflow update is in progress. Please retry.','global-clinic-usp-integration'),array('status'=>409));}try{if(false===$wpdb->query('START TRANSACTION')){return new WP_Error('gcu_transaction_failed',__('The workflow transaction could not start.','global-clinic-usp-integration'),array('status'=>500));}$u=array('status'=>$target,'row_version'=>(int)$row['row_version']+1,'updated_at'=>current_time('mysql',true));if('copy'===$machine&&'founder_approved'===$target){$u['approved_by']=get_current_user_id();$u['approved_at']=current_time('mysql',true);$u['review_due_at']=gmdate('Y-m-d H:i:s',time()+GCU_Policy::COPY_REVIEW_DAYS*DAY_IN_SECONDS);}if('experiment'===$machine&&'approved'===$target){$u['approved_by']=get_current_user_id();}$done=$wpdb->update($table,$u,array('id'=>(int)$row['id'],'row_version'=>(int)$expected));if(1!==$done){$wpdb->query('ROLLBACK');return new WP_Error('gcu_concurrent_update',__('A concurrent update prevented this transition.','global-clinic-usp-integration'),array('status'=>409));}if('copy'===$machine&&'active'===$target){$n=current_time('mysql',true);$sup=$wpdb->query($wpdb->prepare("UPDATE {$t['blocks']} SET status='superseded',row_version=row_version+1,updated_at=%s WHERE block_key=%s AND locale=%s AND id<>%d AND status='active'",$n,$row['block_key'],$row['locale'],(int)$row['id']));if(false===$sup){$wpdb->query('ROLLBACK');return new WP_Error('gcu_supersede_failed',__('Older active content versions could not be superseded safely.','global-clinic-usp-integration'),array('status'=>500));}}if(false===$wpdb->query('COMMIT')){$wpdb->query('ROLLBACK');return new WP_Error('gcu_commit_failed',__('The workflow transaction could not be committed.','global-clinic-usp-integration'),array('status'=>500));}}finally{GCU_Hardening::release_db_lock($lock);}$this->audit('state_transition',$machine,$id,'workflow_governance',$reason,$row,array_merge($row,$u));if('copy'===$machine&&in_array($target,array('active','withdrawn','superseded'),true)){$this->publish_event('ClinicUSPContentPublished.v1',array('public_id'=>$id,'status'=>$target));}return array('public_id'=>$id,'status'=>$target,'row_version'=>$u['row_version']);}
private function validate_transition_target($machine,array$row,$target){global$wpdb;$t=GCU_Install::tables();if('copy'===$machine&&in_array($target,array('founder_approved','active'),true)){$c=json_decode((string)$row['claim_keys'],true);$c=is_array($c)?array_values(array_unique(array_filter(array_map('sanitize_key',$c)))):array();if($c&&count($this->public_claims($c))!==count($c)){return new WP_Error('gcu_claim_dependency_unready',__('All linked claims must be current, public and active before this copy can be approved.','global-clinic-usp-integration'),array('status'=>409));}if($row['cta_destination']){$d=GCU_Plugin::instance()->contracts()->destination($row['cta_destination']);if(empty($d['available'])){return new WP_Error('gcu_destination_unready',__('The linked destination is not ready for active conversion copy.','global-clinic-usp-integration'),array('status'=>409));}}}if('placement'===$machine&&'active'===$target){$b=$wpdb->get_row($wpdb->prepare("SELECT id,slot_key,audience FROM {$t['blocks']} WHERE block_key=%s AND status='active' ORDER BY content_version DESC LIMIT 1",$row['block_key']),ARRAY_A);$block_audience=$b?GCU_Policy::sanitize_audience($b['audience']):'';$placement_audience=GCU_Policy::sanitize_audience(isset($row['audience'])?$row['audience']:'all');$audience_ok=$b&&('all'===$block_audience||$block_audience===$placement_audience);if(!$b||$b['slot_key']!==$row['slot_key']||!$audience_ok||!GCU_Plugin::instance()->contracts()->placement_ready($row)){return new WP_Error('gcu_placement_unready',__('The active block, audience contract or File 20 slot is not ready.','global-clinic-usp-integration'),array('status'=>409));}}if('experiment'===$machine&&in_array($target,array('approved','running'),true)){foreach(array('hypothesis','variants','guardrails','success_metric','sample_policy','privacy_policy','ends_at')as$f){if(empty($row[$f])){return new WP_Error('gcu_experiment_incomplete',__('The experiment is missing required governance fields.','global-clinic-usp-integration'),array('status'=>409));}}$end=strtotime($row['ends_at'].' UTC');if(!$end||$end<=time()||$end>time()+90*DAY_IN_SECONDS){return new WP_Error('gcu_experiment_window_invalid',__('The experiment end date must be within the approved 90-day window.','global-clinic-usp-integration'),array('status'=>409));}}return true;}
public function create_placement(array$d){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}$a=GCU_Capabilities::require_capability(GCU_Capabilities::MANAGE_PLACEMENTS,null,'create_placement');if(is_wp_error($a)){return$a;}$key=sanitize_key(isset($d['placement_key'])?$d['placement_key']:'');$block=sanitize_key(isset($d['block_key'])?$d['block_key']:'');$route=sanitize_key(isset($d['route_key'])?$d['route_key']:'global_clinic');$slot=sanitize_key(isset($d['slot_key'])?$d['slot_key']:'');if(!$key||!$block||'global_clinic'!==$route||!in_array($slot,array('global_clinic_primary','global_clinic_trust','global_clinic_steps','global_clinic_faq'),true)){return new WP_Error('gcu_invalid_placement',__('The placement contract is incomplete or outside File 14 ownership.','global-clinic-usp-integration'),array('status'=>400));}$starts=$this->sanitize_datetime(isset($d['starts_at'])?$d['starts_at']:'');$ends=$this->sanitize_datetime(isset($d['ends_at'])?$d['ends_at']:'');if($starts&&$ends&&strtotime($ends.' UTC')<=strtotime($starts.' UTC')){return new WP_Error('gcu_invalid_placement_window',__('Placement end time must be after its start time.','global-clinic-usp-integration'),array('status'=>400));}global$wpdb;$t=GCU_Install::tables();$now=current_time('mysql',true);$r=array('public_id'=>wp_generate_uuid4(),'placement_key'=>$key,'block_key'=>$block,'route_key'=>$route,'slot_key'=>$slot,'audience'=>GCU_Policy::sanitize_audience(isset($d['audience'])?$d['audience']:'all'),'priority'=>max(1,min(1000,absint(isset($d['priority'])?$d['priority']:100))),'status'=>'planned','starts_at'=>$starts,'ends_at'=>$ends,'created_by'=>get_current_user_id(),'created_at'=>$now,'updated_at'=>$now);if(false===$wpdb->insert($t['placements'],$r)){return new WP_Error('gcu_placement_write_failed',__('The placement could not be created.','global-clinic-usp-integration'),array('status'=>409));}$this->audit('placement_created','placement',$r['public_id'],'placement_governance','',array(),$r);return$this->record_by_public_id('placements',$r['public_id']);}
public function create_experiment(array$d){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}$a=GCU_Capabilities::require_capability(GCU_Capabilities::MANAGE_EXPERIMENTS,null,'create_experiment');if(is_wp_error($a)){return$a;}$key=sanitize_key(isset($d['experiment_key'])?$d['experiment_key']:'');$vars=isset($d['variants'])&&is_array($d['variants'])?GCU_Hardening::sanitize_structured_value($d['variants']):array();$guards=isset($d['guardrails'])&&is_array($d['guardrails'])?GCU_Hardening::sanitize_structured_value($d['guardrails']):array();$hyp=GCU_Hardening::bounded_text(sanitize_textarea_field(isset($d['hypothesis'])?$d['hypothesis']:''),1000);$metric=GCU_Hardening::bounded_text(sanitize_text_field(isset($d['success_metric'])?$d['success_metric']:''),191);$sample=GCU_Hardening::bounded_text(sanitize_textarea_field(isset($d['sample_policy'])?$d['sample_policy']:''),1000);$privacy=GCU_Hardening::bounded_text(sanitize_textarea_field(isset($d['privacy_policy'])?$d['privacy_policy']:''),1000);$ends=$this->sanitize_datetime(isset($d['ends_at'])?$d['ends_at']:'');$end=$ends?strtotime($ends.' UTC'):0;if(!$key||!$hyp||count($vars)<2||!$guards||!$metric||!$sample||!$privacy||!$end||$end<=time()||$end>time()+90*DAY_IN_SECONDS){return new WP_Error('gcu_invalid_experiment',__('The experiment requires complete governance fields and an end date within 90 days.','global-clinic-usp-integration'),array('status'=>400));}$scan=strtolower($sample.' '.$privacy);foreach(array('minor profiling','health profiling','patient profiling','identity evidence','diagnosis targeting')as$f){if(false!==strpos($scan,$f)){return new WP_Error('gcu_sensitive_experiment_forbidden',__('Sensitive or minor profiling is not permitted by the default File 14 experiment contract.','global-clinic-usp-integration'),array('status'=>400));}}global$wpdb;$t=GCU_Install::tables();$now=current_time('mysql',true);$r=array('public_id'=>wp_generate_uuid4(),'experiment_key'=>$key,'hypothesis'=>$hyp,'variants'=>wp_json_encode($vars),'audience'=>GCU_Policy::sanitize_audience(isset($d['audience'])?$d['audience']:'all'),'guardrails'=>wp_json_encode($guards),'success_metric'=>$metric,'sample_policy'=>$sample,'privacy_policy'=>$privacy,'status'=>'proposed','starts_at'=>null,'ends_at'=>$ends,'created_by'=>get_current_user_id(),'created_at'=>$now,'updated_at'=>$now);if(false===$wpdb->insert($t['experiments'],$r)){return new WP_Error('gcu_experiment_write_failed',__('The experiment could not be created.','global-clinic-usp-integration'),array('status'=>409));}$this->audit('experiment_proposed','experiment',$r['public_id'],'experiment_governance','',array(),$r);return$this->record_by_public_id('experiments',$r['public_id']);}
public function withdraw_claim($claim,$expected,$reason){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}$a=GCU_Capabilities::require_capability(GCU_Capabilities::APPROVE_CLAIMS,$claim,'withdraw_claim');if(is_wp_error($a)){return$a;}$reason=GCU_Hardening::bounded_text(sanitize_textarea_field($reason),self::MAX_REASON);if((function_exists('mb_strlen')?mb_strlen($reason):strlen($reason))<8){return new WP_Error('gcu_reason_required',__('A meaningful bounded withdrawal reason is required.','global-clinic-usp-integration'),array('status'=>400));}global$wpdb;$t=GCU_Install::tables();$key=sanitize_key($claim);$lock=GCU_Hardening::acquire_db_lock('claim:'.$key);if(!$lock){return new WP_Error('gcu_claim_lock_busy',__('Another claim update is in progress.','global-clinic-usp-integration'),array('status'=>409));}try{$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['claims']} WHERE claim_key=%s",$key),ARRAY_A);if(!$row){return new WP_Error('gcu_claim_not_found',__('The claim was not found.','global-clinic-usp-integration'),array('status'=>404));}if((int)$row['row_version']!==(int)$expected){return new WP_Error('gcu_version_conflict',__('The claim changed. Reload it before retrying.','global-clinic-usp-integration'),array('status'=>409));}if(false===$wpdb->query('START TRANSACTION')){return new WP_Error('gcu_claim_transaction_failed',__('Claim withdrawal transaction could not start.','global-clinic-usp-integration'),array('status'=>500));}$h=array('claim_key'=>$key,'row_version'=>(int)$row['row_version'],'status'=>$row['status'],'claim_hash'=>hash('sha256',wp_json_encode($row)),'reason'=>$reason,'snapshot'=>wp_json_encode($row),'actor_id'=>get_current_user_id(),'created_at'=>current_time('mysql',true));$ins=$wpdb->query($wpdb->prepare("INSERT IGNORE INTO {$t['claim_history']} (claim_key,row_version,status,claim_hash,reason,snapshot,actor_id,created_at) VALUES (%s,%d,%s,%s,%s,%s,%d,%s)",$h['claim_key'],$h['row_version'],$h['status'],$h['claim_hash'],$h['reason'],$h['snapshot'],$h['actor_id'],$h['created_at']));if(false===$ins){$wpdb->query('ROLLBACK');return new WP_Error('gcu_claim_history_failed',__('Claim history could not be recorded safely.','global-clinic-usp-integration'),array('status'=>500));}$u=array('status'=>'withdrawn','is_public'=>0,'row_version'=>(int)$row['row_version']+1,'updated_at'=>current_time('mysql',true));$done=$wpdb->update($t['claims'],$u,array('id'=>(int)$row['id'],'row_version'=>(int)$expected));if(1!==$done||false===$wpdb->query('COMMIT')){$wpdb->query('ROLLBACK');return new WP_Error('gcu_claim_withdraw_failed',__('The claim could not be withdrawn atomically.','global-clinic-usp-integration'),array('status'=>409));}}finally{GCU_Hardening::release_db_lock($lock);}$this->audit('claim_withdrawn','claim',$key,'claim_governance',$reason,$row,array_merge($row,$u));$this->publish_event('ClinicUSPClaimWithdrawn.v1',array('claim_key'=>$key));return array('claim_key'=>$key,'status'=>'withdrawn','row_version'=>$u['row_version']);}
public function record_by_public_id($key,$id){global$wpdb;$t=GCU_Install::tables();if(!isset($t[$key])||!in_array($key,array('blocks','placements','experiments'),true)){return null;}$table=$t[$key];return$wpdb->get_row($wpdb->prepare("SELECT * FROM `$table` WHERE public_id=%s",sanitize_text_field($id)),ARRAY_A);}
public function issue_event_token($purpose='measurement'){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}if(!GCU_Privacy::measurement_allowed()||GCU_Hardening::is_sensitive_path()){return new WP_Error('gcu_measurement_not_allowed',__('Measurement is not permitted in this context.','global-clinic-usp-integration'),array('status'=>403));}$rate=$this->consume_rate_limit('token-issue',30);if(is_wp_error($rate)){return$rate;}global$wpdb;$t=GCU_Install::tables();$id=wp_generate_uuid4();try{$secret=bin2hex(random_bytes(24));}catch(Exception$e){return new WP_Error('gcu_entropy_unavailable',__('A secure event token could not be created.','global-clinic-usp-integration'),array('status'=>503));}$token=$id.'.'.$secret;$r=array('token_id'=>$id,'token_hash'=>hash('sha256',$token),'purpose'=>sanitize_key($purpose),'expires_at'=>gmdate('Y-m-d H:i:s',time()+GCU_Policy::EVENT_TOKEN_TTL),'created_at'=>current_time('mysql',true));if(false===$wpdb->insert($t['event_tokens'],$r)){return new WP_Error('gcu_event_token_write_failed',__('The event token could not be issued.','global-clinic-usp-integration'),array('status'=>500));}return array('token'=>$token,'expires_in'=>GCU_Policy::EVENT_TOKEN_TTL);}
public function consume_event_token($token,$purpose='measurement'){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}$token=sanitize_text_field((string)$token);if(!preg_match('/^[a-f0-9\-]{36}\.[a-f0-9]{48}$/',$token)){return new WP_Error('gcu_event_token_invalid',__('A valid event token is required.','global-clinic-usp-integration'),array('status'=>403));}global$wpdb;$t=GCU_Install::tables();$done=$wpdb->query($wpdb->prepare("UPDATE {$t['event_tokens']} SET consumed_at=%s WHERE token_hash=%s AND purpose=%s AND consumed_at IS NULL AND expires_at>UTC_TIMESTAMP()",current_time('mysql',true),hash('sha256',$token),sanitize_key($purpose)));return 1===$done?true:new WP_Error('gcu_event_token_expired',__('The event token expired or was already used.','global-clinic-usp-integration'),array('status'=>403));}
public function consume_rate_limit($scope,$limit=60){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}global$wpdb;$t=GCU_Install::tables();$id=is_user_logged_in()?'u:'.get_current_user_id():'a:'.(isset($_SERVER['REMOTE_ADDR'])?sanitize_text_field(wp_unslash($_SERVER['REMOTE_ADDR'])):'unknown');$bucket=hash_hmac('sha256',sanitize_key($scope).'|'.$id.'|'.gmdate('YmdHi'),wp_salt('auth'));$sql=$wpdb->prepare("INSERT INTO {$t['rate_limits']} (bucket_key,counter,expires_at,updated_at) VALUES (%s,1,%s,%s) ON DUPLICATE KEY UPDATE counter=counter+1,expires_at=VALUES(expires_at),updated_at=VALUES(updated_at)",$bucket,gmdate('Y-m-d H:i:s',time()+120),current_time('mysql',true));if(false===$wpdb->query($sql)){return new WP_Error('gcu_rate_limit_store_failed',__('The request could not be rate-limited safely.','global-clinic-usp-integration'),array('status'=>503));}$count=(int)$wpdb->get_var($wpdb->prepare("SELECT counter FROM {$t['rate_limits']} WHERE bucket_key=%s",$bucket));return$count>max(1,(int)$limit)?new WP_Error('gcu_rate_limited',__('Too many requests. Please retry later.','global-clinic-usp-integration'),array('status'=>429)):$count;}
public function record_event(array$d){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}if(!GCU_Privacy::measurement_allowed()||GCU_Hardening::is_sensitive_path()){return new WP_Error('gcu_consent_required',__('Measurement consent is required and this route must be eligible.','global-clinic-usp-integration'),array('status'=>403));}$rate=$this->consume_rate_limit('measurement',GCU_Policy::EVENT_RATE_LIMIT);if(is_wp_error($rate)){return$rate;}$stage=sanitize_key(isset($d['stage'])?$d['stage']:'');if(!in_array($stage,array('impression','cta_selected','destination_loaded','application_started','booking_started'),true)){return new WP_Error('gcu_invalid_stage',__('Unknown funnel stage.','global-clinic-usp-integration'),array('status'=>400));}$dest=sanitize_key(isset($d['destination'])?$d['destination']:'');$reg=GCU_Plugin::instance()->contracts()->destination_registry();if($dest&&!isset($reg[$dest])){return new WP_Error('gcu_invalid_destination',__('Unknown funnel destination.','global-clinic-usp-integration'),array('status'=>400));}if('application_started'===$stage&&'doctor_onboarding'!==$dest||'booking_started'===$stage&&'clinic'!==$dest){return new WP_Error('gcu_stage_destination_mismatch',__('The funnel stage does not match its owner destination.','global-clinic-usp-integration'),array('status'=>400));}global$wpdb;$t=GCU_Install::tables();$c=GCU_Policy::sanitize_campaign(isset($d['campaign'])&&is_array($d['campaign'])?$d['campaign']:array());$id=isset($d['event_id'])&&wp_is_uuid($d['event_id'])?$d['event_id']:wp_generate_uuid4();$subject=GCU_Plugin::instance()->privacy()->event_subject_hash();$ins=$wpdb->query($wpdb->prepare("INSERT IGNORE INTO {$t['events']} (event_id,event_type,event_version,funnel_stage,destination_key,subject_hash,source_value,medium_value,campaign_value,ref_value,consent_state,occurred_at,created_at) VALUES (%s,'ClinicUSPFunnelEvent',1,%s,%s,%s,%s,%s,%s,%s,'granted',%s,%s)",$id,$stage,$dest,$subject,$c['source'],$c['medium'],$c['campaign'],$c['ref'],current_time('mysql',true),current_time('mysql',true)));if(false===$ins){return new WP_Error('gcu_event_write_failed',__('The event could not be recorded.','global-clinic-usp-integration'),array('status'=>500));}if('cta_selected'===$stage&&1===$ins){$this->publish_event('ClinicUSPCTASelected.v1',array('source_event_id'=>$id,'destination'=>$dest));}return array('event_id'=>$id,'deduplicated'=>0===$ins);}
public function funnel_summary($days=30){$a=GCU_Capabilities::require_capability(GCU_Capabilities::VIEW_ANALYTICS,null,'view_funnel_summary');if(is_wp_error($a)){return$a;}global$wpdb;$days=max(1,min(self::EVENT_RETENTION_DAYS,absint($days)));$t=GCU_Install::tables();$rows=$wpdb->get_results($wpdb->prepare("SELECT funnel_stage,COUNT(*) AS total FROM {$t['events']} WHERE occurred_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL %d DAY) GROUP BY funnel_stage ORDER BY funnel_stage",$days),ARRAY_A);$total=array_sum(array_map(static function($r){return(int)$r['total'];},is_array($rows)?$rows:array()));if($total<10){return array('suppressed'=>true,'threshold'=>10,'days'=>$days,'stages'=>array(),'suppressed_stages'=>array());}$safe=array();$suppressed=array();foreach(is_array($rows)?$rows:array()as$row){$n=(int)$row['total'];if($n<10){$suppressed[]=sanitize_key($row['funnel_stage']);$row['total']=null;$row['suppressed']=true;}else{$row['total']=$n;$row['suppressed']=false;}$safe[]=$row;}return array('suppressed'=>false,'threshold'=>10,'days'=>$days,'stages'=>$safe,'suppressed_stages'=>$suppressed);}
public function content_by_public_id($id){global$wpdb;$t=GCU_Install::tables();return$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['blocks']} WHERE public_id=%s",sanitize_text_field($id)),ARRAY_A);}
public function run_idempotent_command($name,$supplied,callable$callback){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}global$wpdb;$t=GCU_Install::tables();$key=GCU_Hardening::command_key($name,$supplied);$now=current_time('mysql',true);$ins=$wpdb->query($wpdb->prepare("INSERT IGNORE INTO {$t['commands']} (command_key,command_name,actor_id,status,attempts,locked_at,created_at,updated_at) VALUES (%s,%s,%d,'processing',1,%s,%s,%s)",$key,sanitize_key($name),get_current_user_id(),$now,$now,$now));if(false===$ins){return new WP_Error('gcu_command_store_failed',__('The idempotent command state could not be stored.','global-clinic-usp-integration'),array('status'=>503));}if(0===$ins){$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['commands']} WHERE command_key=%s",$key),ARRAY_A);if($row&&'complete'===$row['status']){$r=json_decode((string)$row['result_json'],true);return is_array($r)?$r:array();}$stale=$row&&!empty($row['locked_at'])&&strtotime($row['locked_at'].' UTC')<time()-300;if(!$row||'processing'===$row['status']&&!$stale||(int)$row['attempts']>=3){return new WP_Error('gcu_command_conflict',__('This command is already processing or has exhausted its safe retries.','global-clinic-usp-integration'),array('status'=>409));}$claimed=$wpdb->query($wpdb->prepare("UPDATE {$t['commands']} SET status='processing',attempts=attempts+1,error_code=NULL,locked_at=%s,updated_at=%s WHERE command_key=%s AND (status='failed' OR (status='processing' AND locked_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 5 MINUTE)))",$now,$now,$key));if(1!==$claimed){return new WP_Error('gcu_command_conflict',__('This command could not be safely reclaimed.','global-clinic-usp-integration'),array('status'=>409));}}try{$r=call_user_func($callback);}catch(Throwable$e){$this->fail_command($key,'exception');return new WP_Error('gcu_command_failed',__('The command failed safely.','global-clinic-usp-integration'),array('status'=>500));}if(is_wp_error($r)){$this->fail_command($key,$r->get_error_code());return$r;}$done=$wpdb->query($wpdb->prepare("UPDATE {$t['commands']} SET status='complete',result_json=%s,error_code=NULL,locked_at=NULL,updated_at=%s WHERE command_key=%s AND status='processing'",wp_json_encode($r),current_time('mysql',true),$key));return 1===$done?$r:new WP_Error('gcu_command_completion_failed',__('The command result could not be committed safely.','global-clinic-usp-integration'),array('status'=>500));}
private function fail_command($key,$code){global$wpdb;$t=GCU_Install::tables();$wpdb->query($wpdb->prepare("UPDATE {$t['commands']} SET status='failed',error_code=%s,locked_at=NULL,updated_at=%s WHERE command_key=%s AND status='processing'",sanitize_key($code),current_time('mysql',true),$key));}
public function audit($action,$type,$id,$purpose,$reason,array$before,array$after){global$wpdb;$t=GCU_Install::tables();$lock=GCU_Hardening::acquire_db_lock('audit-chain',3);if(!$lock){update_option('gcu_enabled',0,false);GCU_Observability::log('error','audit_lock_failed',array('action'=>$action));return false;}try{$prev=(string)$wpdb->get_var("SELECT row_hash FROM {$t['audit']} ORDER BY id DESC LIMIT 1");if(''===$prev){$prev=str_repeat('0',64);}$r=array('trace_id'=>GCU_Policy::trace_id(),'actor_id'=>get_current_user_id(),'action_name'=>sanitize_key($action),'object_type'=>sanitize_key($type),'object_id'=>GCU_Hardening::bounded_text(sanitize_text_field($id),191),'purpose'=>GCU_Hardening::bounded_text(sanitize_key($purpose),100),'reason'=>GCU_Hardening::bounded_text(sanitize_textarea_field($reason),self::MAX_REASON),'before_hash'=>$before?hash('sha256',wp_json_encode($before)):null,'after_hash'=>$after?hash('sha256',wp_json_encode($after)):null,'previous_hash'=>$prev,'created_at'=>current_time('mysql',true));$r['row_hash']=$this->audit_row_hash($r);if(false===$wpdb->insert($t['audit'],$r)){update_option('gcu_enabled',0,false);GCU_Observability::log('error','audit_write_failed',array('action'=>$action));return false;}return$r['trace_id'];}finally{GCU_Hardening::release_db_lock($lock);}}
private function audit_row_hash(array$r){return hash_hmac('sha256',implode('|',array($r['previous_hash'],$r['trace_id'],(string)$r['actor_id'],$r['action_name'],$r['object_type'],$r['object_id'],$r['purpose'],(string)$r['reason'],(string)$r['before_hash'],(string)$r['after_hash'],$r['created_at'])),wp_salt('auth'));}
public function verify_audit_chain($limit=5000){global$wpdb;$t=GCU_Install::tables();$total=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$t['audit']}");$limit=max(1,min(10000,(int)$limit));$offset=max(0,$total-$limit);if(0===$offset){$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$t['audit']} ORDER BY id ASC LIMIT %d",$limit),ARRAY_A);$prev=str_repeat('0',64);$scope='full';}else{$anchor=(string)$wpdb->get_var($wpdb->prepare("SELECT row_hash FROM {$t['audit']} ORDER BY id ASC LIMIT 1 OFFSET %d",$offset-1));if(!preg_match('/^[a-f0-9]{64}$/',$anchor)){return array('valid'=>false,'scope'=>'anchor_missing','checked'=>0,'total'=>$total);}$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$t['audit']} ORDER BY id ASC LIMIT %d OFFSET %d",$limit,$offset),ARRAY_A);$prev=$anchor;$scope='recent_tail';}$checked=0;foreach(is_array($rows)?$rows:array()as$row){$checked++;if(!hash_equals($prev,(string)$row['previous_hash'])||!hash_equals((string)$row['row_hash'],$this->audit_row_hash($row))){return array('valid'=>false,'scope'=>'failed','checked'=>$checked,'total'=>$total,'offset'=>$offset);}$prev=(string)$row['row_hash'];}return array('valid'=>true,'scope'=>$scope,'checked'=>$checked,'total'=>$total,'offset'=>$offset);}
public function publish_event($name,array$payload){global$wpdb;$t=GCU_Install::tables();$id=wp_generate_uuid4();$payload['event_id']=$id;$payload['event_name']=sanitize_text_field($name);$payload['event_version']=1;$payload['occurred_at']=gmdate('c');$payload=GCU_Hardening::sanitize_structured_value($payload);$enc=wp_json_encode($payload);if(false===$enc||strlen($enc)>20000){update_option('gcu_enabled',0,false);GCU_Observability::log('error','outbox_payload_invalid',array('event'=>$name));return false;}$ins=$wpdb->insert($t['outbox'],array('event_id'=>$id,'event_name'=>sanitize_text_field($name),'event_version'=>1,'payload'=>$enc,'status'=>'pending','attempts'=>0,'created_at'=>current_time('mysql',true)));if(false===$ins){update_option('gcu_enabled',0,false);GCU_Observability::log('error','outbox_write_failed',array('event'=>$name));return false;}$this->dispatch_outbox($id,1);return$id;}
public function dispatch_outbox($event_id='',$limit=20){global$wpdb;$t=GCU_Install::tables();$limit=max(1,min(100,(int)$limit));$where="(status IN ('pending','retry') AND (next_attempt_at IS NULL OR next_attempt_at<=UTC_TIMESTAMP())) OR (status='processing' AND locked_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 10 MINUTE))";$args=array();if($event_id){$where="event_id=%s AND ($where)";$args[]=sanitize_text_field($event_id);}$sql="SELECT * FROM {$t['outbox']} WHERE $where ORDER BY id ASC LIMIT $limit";$rows=$args?$wpdb->get_results($wpdb->prepare($sql,$args),ARRAY_A):$wpdb->get_results($sql,ARRAY_A);foreach(is_array($rows)?$rows:array()as$row){$claim=$wpdb->query($wpdb->prepare("UPDATE {$t['outbox']} SET status='processing',locked_at=%s,attempts=attempts+1 WHERE id=%d AND ((status IN ('pending','retry') AND (next_attempt_at IS NULL OR next_attempt_at<=UTC_TIMESTAMP())) OR (status='processing' AND locked_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 10 MINUTE)))",current_time('mysql',true),(int)$row['id']));if(1!==$claim){continue;}try{do_action($row['event_name'],json_decode((string)$row['payload'],true));$wpdb->query($wpdb->prepare("UPDATE {$t['outbox']} SET status='sent',locked_at=NULL,next_attempt_at=NULL,last_error_code=NULL,dispatched_at=%s WHERE id=%d AND status='processing'",current_time('mysql',true),(int)$row['id']));}catch(Throwable$e){$attempt=(int)$row['attempts']+1;$status=$attempt>=5?'dead':'retry';$delay=min(3600,60*(1<<min(5,$attempt)));$wpdb->query($wpdb->prepare("UPDATE {$t['outbox']} SET status=%s,locked_at=NULL,next_attempt_at=%s,last_error_code='dispatch_exception' WHERE id=%d AND status='processing'",$status,gmdate('Y-m-d H:i:s',time()+$delay),(int)$row['id']));}}return is_array($rows)?count($rows):0;}
public function accept_inbound_event($name,array$payload){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return false;}$v=$this->validate_inbound_event($name,$payload);if(is_wp_error($v)){return false;}global$wpdb;$t=GCU_Install::tables();$clean=GCU_Hardening::sanitize_structured_value($payload);$enc=wp_json_encode($clean);if(false===$enc){return false;}$hash=hash('sha256',$enc);$event_id=sanitize_text_field($payload['event_id']);$event_name=sanitize_text_field($name);$ins=$wpdb->query($wpdb->prepare("INSERT IGNORE INTO {$t['inbox']} (event_id,event_name,payload_hash,payload,status,attempts,created_at) VALUES (%s,%s,%s,%s,'pending',0,%s)",$event_id,$event_name,$hash,$enc,current_time('mysql',true)));if(false===$ins){return false;}if(0===$ins){$existing=$wpdb->get_row($wpdb->prepare("SELECT event_name,payload_hash FROM {$t['inbox']} WHERE event_id=%s",$event_id),ARRAY_A);if(!$existing||!hash_equals((string)$existing['payload_hash'],$hash)||!hash_equals((string)$existing['event_name'],$event_name)){GCU_Observability::log('warning','inbound_event_identity_conflict',array('event_id'=>$event_id,'event_name'=>$event_name));return false;}}if(1===$ins){$this->process_inbox($event_id,1);}return true;}
private function validate_inbound_event($name,array$p){if(!in_array($name,array('DoctorDirectoryAvailable.v1','ClinicBookingAvailable.v1','DoctorOnboardingAvailable.v1','BusinessPolicyChanged.v1'),true)||empty($p['event_id'])||!wp_is_uuid($p['event_id'])){return new WP_Error('gcu_inbound_schema_invalid','Invalid event envelope.');}if('BusinessPolicyChanged.v1'!==$name){if(!array_key_exists('available',$p)||!is_bool($p['available'])){return new WP_Error('gcu_inbound_schema_invalid','Availability events require a boolean available field.');}if(!empty($p['url'])&&!GCU_Hardening::strict_same_origin_url($p['url'])){return new WP_Error('gcu_inbound_url_invalid','Availability event URL is not same-origin.');}}return true;}
public function process_inbox($event_id='',$limit=20){global$wpdb;$t=GCU_Install::tables();$limit=max(1,min(100,(int)$limit));$where="(status IN ('pending','retry') AND (next_attempt_at IS NULL OR next_attempt_at<=UTC_TIMESTAMP())) OR (status='processing' AND locked_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 10 MINUTE))";$args=array();if($event_id){$where="event_id=%s AND ($where)";$args[]=sanitize_text_field($event_id);}$sql="SELECT * FROM {$t['inbox']} WHERE $where ORDER BY id ASC LIMIT $limit";$rows=$args?$wpdb->get_results($wpdb->prepare($sql,$args),ARRAY_A):$wpdb->get_results($sql,ARRAY_A);foreach(is_array($rows)?$rows:array()as$row){$claim=$wpdb->query($wpdb->prepare("UPDATE {$t['inbox']} SET status='processing',locked_at=%s,attempts=attempts+1 WHERE id=%d AND ((status IN ('pending','retry') AND (next_attempt_at IS NULL OR next_attempt_at<=UTC_TIMESTAMP())) OR (status='processing' AND locked_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 10 MINUTE)))",current_time('mysql',true),(int)$row['id']));if(1!==$claim){continue;}try{$r=GCU_Plugin::instance()->contracts()->apply_inbound_event($row['event_name'],json_decode((string)$row['payload'],true));if(is_wp_error($r)){throw new RuntimeException($r->get_error_code());}$wpdb->query($wpdb->prepare("UPDATE {$t['inbox']} SET status='processed',locked_at=NULL,next_attempt_at=NULL,last_error_code=NULL,processed_at=%s WHERE id=%d AND status='processing'",current_time('mysql',true),(int)$row['id']));}catch(Throwable$e){$attempt=(int)$row['attempts']+1;$status=$attempt>=5?'dead':'retry';$delay=min(3600,60*(1<<min(5,$attempt)));$wpdb->query($wpdb->prepare("UPDATE {$t['inbox']} SET status=%s,locked_at=NULL,next_attempt_at=%s,last_error_code='process_exception' WHERE id=%d AND status='processing'",$status,gmdate('Y-m-d H:i:s',time()+$delay),(int)$row['id']));}}return is_array($rows)?count($rows):0;}
public function cleanup_lifecycle(){global$wpdb;$t=GCU_Install::tables();return array('tokens'=>$wpdb->query("DELETE FROM {$t['event_tokens']} WHERE expires_at<UTC_TIMESTAMP() OR consumed_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 DAY)"),'rate_limits'=>$wpdb->query("DELETE FROM {$t['rate_limits']} WHERE expires_at<UTC_TIMESTAMP()"),'events'=>$wpdb->query($wpdb->prepare("DELETE FROM {$t['events']} WHERE occurred_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL %d DAY) LIMIT 500",self::EVENT_RETENTION_DAYS)),'outbox'=>$wpdb->query("DELETE FROM {$t['outbox']} WHERE status='sent' AND dispatched_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY) LIMIT 500"),'inbox'=>$wpdb->query("DELETE FROM {$t['inbox']} WHERE status='processed' AND processed_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY) LIMIT 500"),'commands'=>$wpdb->query("DELETE FROM {$t['commands']} WHERE status='complete' AND updated_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 7 DAY) LIMIT 500"));}
private function sanitize_datetime($v){$v=sanitize_text_field((string)$v);if(''===$v){return null;}$t=strtotime($v.' UTC');return$t?gmdate('Y-m-d H:i:s',$t):null;}
}
